package com.alsafa.native4.core;import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;
/** Append-only repair history: status changes, notes and newly added parts. */
public final class RepairUpdateStore{private final CoreStore.DbProvider provider;public RepairUpdateStore(CoreStore.DbProvider p){provider=p;}
 public void note(String repairId,String note){String n=trim(note);if(n.isEmpty())throw new IllegalArgumentException("اكتب تحديث الصيانة");SQLiteDatabase db=provider.db();long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("update_id","rup-"+UUID.randomUUID());v.put("repair_id",repairId);v.put("kind","NOTE");v.put("note",n);v.put("created_at",now);db.insertOrThrow("repair_updates",null,v);}
 public List<Item> list(String repairId){ArrayList<Item> out=new ArrayList<>();try(Cursor c=provider.db().rawQuery("SELECT kind,COALESCE(status,''),COALESCE(note,''),COALESCE(part_name,''),part_qty,created_at FROM repair_updates WHERE repair_id=? ORDER BY created_at DESC",new String[]{repairId})){while(c.moveToNext())out.add(new Item(c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getInt(4),c.getLong(5)));}return out;}
 static void status(SQLiteDatabase db,String repairId,String status,long now){ContentValues v=new ContentValues();v.put("update_id","rup-"+UUID.randomUUID());v.put("repair_id",repairId);v.put("kind","STATUS");v.put("status",status);v.put("created_at",now);db.insertOrThrow("repair_updates",null,v);}
 static void part(SQLiteDatabase db,String repairId,String partId,String name,int qty,long now){ContentValues v=new ContentValues();v.put("update_id","rup-"+UUID.randomUUID());v.put("repair_id",repairId);v.put("kind","PART");v.put("part_id",partId);v.put("part_name",name);v.put("part_qty",qty);v.put("note","تمت إضافة قطعة صيانة جديدة");v.put("created_at",now);db.insertOrThrow("repair_updates",null,v);}
 public static final class Item{public final String kind,status,note,partName;public final int partQty;public final long createdAt;Item(String k,String s,String n,String p,int q,long at){kind=k;status=s;note=n;partName=p;partQty=q;createdAt=at;}}
 private static String trim(String s){return s==null?"":s.trim();}}